package africa.growtogether.platform.ewe.task; import africa.growtogether.platform.common.persistence.AuditedTenantEntity; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="ewe_routing_rules",uniqueConstraints=@UniqueConstraint(name="uk_ewe_route",columnNames={"tenant_id","workflow_definition_id","task_key","priority"})) public class WorkflowRoutingRule extends AuditedTenantEntity { @Column(name="workflow_definition_id",nullable=false) private UUID workflowDefinitionId; @Column(name="task_key",nullable=false,length=120) private String taskKey; @Column(name="priority",nullable=false) private int priority; @Column(name="condition_expression",length=1000) private String conditionExpression; @Enumerated(EnumType.STRING) @Column(name="assignment_type",nullable=false,length=20) private AssignmentType assignmentType; @Column(name="assignment_value",nullable=false,length=500) private String assignmentValue; @Column(name="active",nullable=false) private boolean active=true; protected WorkflowRoutingRule(){} public WorkflowRoutingRule(UUID d,String key,int priority,String condition,AssignmentType type,String value){workflowDefinitionId=d;taskKey=key.trim().toUpperCase();this.priority=priority;conditionExpression=condition;assignmentType=type;assignmentValue=value;} public UUID getWorkflowDefinitionId(){return workflowDefinitionId;} public String getTaskKey(){return taskKey;} public int getPriority(){return priority;} public String getConditionExpression(){return conditionExpression;} public AssignmentType getAssignmentType(){return assignmentType;} public String getAssignmentValue(){return assignmentValue;} public boolean isActive(){return active;} }